  "Captions": "कैप्शन",
  "Captions changed while you had an unsaved draft. Your draft is kept here for comparison.": "आपके बिना सेव किए ड्राफ़्ट के दौरान कैप्शन बदले। तुलना के लिए ड्राफ़्ट यहाँ सुरक्षित है।",
  "Captions changed while you were editing. Load the saved captions before applying another revision.": "संपादन के दौरान कैप्शन बदले। अगला संशोधन लागू करने से पहले सेव किए कैप्शन लोड करें।",
