  "Carry useful ideas into your own brief with your subject, message, and references. Check the result against your actual source material.": "उपयोगी विचार अपने विषय, संदेश और संदर्भों वाले विवरण में लाएँ। परिणाम को अपनी वास्तविक स्रोत सामग्री से मिलाएँ।",
  "Center": "बीच में",
  "Challenge an assumption, then earn attention with a specific alternative.": "किसी धारणा को चुनौती दें, फिर स्पष्ट विकल्प से ध्यान पाएँ।",
