  "Change the filters or run custom research. REELassati will show fewer results rather than fill the feed with stale, paid, generic, or unverified content.": "फ़िल्टर बदलें या कस्टम शोध करें। REELassati पुरानी, सशुल्क, सामान्य या असत्यापित सामग्री से फ़ीड भरने के बजाय कम परिणाम दिखाएगा।",
  "Change the search or filter to reveal more items.": "अधिक सामग्री देखने के लिए खोज या फ़िल्टर बदलें।",
  "Changes appear on your timeline as they finish. You can keep editing them by hand.": "बदलाव पूरे होने पर टाइमलाइन में दिखेंगे। आप मैन्युअल संपादन जारी रख सकते हैं।",
  "Changes are saved as an undoable revision.": "बदलाव पूर्ववत किए जा सकने वाले संशोधन के रूप में सेव होते हैं।",
