  "Human support": "सहायता कर्मी",
  "Human support has been notified by email.": "सहायता कर्मी को ईमेल से सूचित किया गया।",
  "Human-approved publishing and scheduling for connected accounts.": "जुड़े खातों के लिए व्यक्ति की मंज़ूरी से प्रकाशन और शेड्यूलिंग।",
  "Human-created": "मनुष्य द्वारा निर्मित",
  "I agree to the ": "मैं निम्न से सहमत हूँ: ",
  "I am authorized to download and use this video.": "मुझे यह वीडियो डाउनलोड और उपयोग करने का अधिकार है।",
  "I can't access my account": "मैं अपने खाते में नहीं जा पा रहा",
  "I hold documented consent or another verified legal basis.": "मेरे पास दर्ज सहमति या अन्य सत्यापित कानूनी आधार है।",
  "I may download this reference and submit it to the AI analysis provider.": "मुझे यह संदर्भ डाउनलोड करके AI विश्लेषण प्रदाता को भेजने का अधिकार है।",
  "I may use the prompt, brands, references, faces and voices in this generation.": "मुझे इस जनरेशन में प्रॉम्प्ट, ब्रांड, संदर्भ, चेहरे और आवाज़ें उपयोग करने का अधिकार है।",
  "I may use this prompt, its brands, and its likenesses.": "मुझे यह प्रॉम्प्ट, इसके ब्रांड और व्यक्तियों के रूप उपयोग करने का अधिकार है।",
  "I may use this text and voice. If the voice identifies a real person, I have documented consent or another verified legal basis.": "मुझे यह टेक्स्ट और आवाज़ उपयोग करने का अधिकार है। आवाज़ से वास्तविक व्यक्ति पहचाना जाए तो मेरे पास दर्ज सहमति या अन्य सत्यापित कानूनी आधार है।",
  "I need to open a support ticket": "मुझे सहायता टिकट खोलना है",
  "Idea — improvement request": "विचार — सुधार अनुरोध",
  "Ideas": "विचार",
  "Identity and contact details for the REELassati service provider.": "REELassati सेवा प्रदाता की पहचान और संपर्क विवरण।",
  "If a feature is not accessible, tell us the page, action, device, and assistive technology. We prioritise barriers affecting sign-in, purchase, creation, and account management: ": "सुविधा सुलभ न हो तो पेज, काम, डिवाइस और सहायक तकनीक बताएँ। हम साइन इन, खरीद, निर्माण और खाता प्रबंधन की बाधाएँ पहले देखते हैं: ",
  "If a ticket is prepared, review its subject, description, and contact details before sending it. A prepared ticket is sent only after you submit it.": "टिकट तैयार हो तो भेजने से पहले विषय, विवरण और संपर्क जाँचें। टिकट आपके जमा करने के बाद ही भेजा जाता है।",
  "If content appears to misuse your likeness, voice, work, or personal information, contact the human support channel with the relevant page, asset, or publication reference.": "आपके रूप, आवाज़, कृति या निजी जानकारी का दुरुपयोग दिखे तो संबंधित पेज, सामग्री या प्रकाशन संदर्भ सहित सहायता कर्मी से संपर्क करें।",
  "If the page reports a failure, return to Sign in and try the same account method again. Include the error when contacting support.": "पेज विफलता बताए तो साइन इन लौटकर वही खाता तरीका फिर आज़माएँ। सहायता संपर्क में त्रुटि बताएँ।",
  "If you buy as a consumer in the EEA or a country with equivalent rights, a statutory withdrawal period may apply, commonly 14 days for distance contracts. If you request immediate service, you may owe a proportionate amount for service already supplied. Loss of withdrawal rights for digital content occurs only when all legal requirements, including express consent and acknowledgement, are met. To exercise a right, send an unambiguous statement with your account email and purchase to ": "EEA या समान अधिकार वाले देश में उपभोक्ता खरीद पर कानूनी वापसी अवधि लागू हो सकती है, जो दूरस्थ अनुबंधों में सामान्यतः 14 दिन है। तुरंत सेवा माँगने पर दी जा चुकी सेवा का आनुपातिक भुगतान देना पड़ सकता है। डिजिटल सामग्री का वापसी अधिकार स्पष्ट सहमति और पुष्टि सहित सभी कानूनी शर्तें पूरी होने पर ही समाप्त होता है। अधिकार उपयोग करने के लिए खाता ईमेल और खरीद सहित स्पष्ट वक्तव्य यहाँ भेजें: ",
  "If you received a code, enter it in the claim section and read the confirmation or eligibility message.": "कोड मिला हो तो दावा हिस्से में डालकर पुष्टि या पात्रता संदेश पढ़ें।",
  "If you used a social sign-in provider, use that provider’s access flow. Contact support if the account remains inaccessible.": "सोशल साइन इन उपयोग किया है तो उसी प्रदाता की पहुँच प्रक्रिया अपनाएँ। खाता फिर भी न खुले तो सहायता से संपर्क करें।",
