  "Legal remedies for a non-conforming digital service remain available. Failed generations automatically release reserved credits. For duplicate charges, missing access, undelivered credits, or persistent problems, contact support; we will verify payment and usage records and apply a refund, credit restoration, or another appropriate remedy.": "अनुबंध के अनुरूप न होने वाली डिजिटल सेवा के कानूनी उपाय उपलब्ध रहते हैं। विफल जनरेशन आरक्षित क्रेडिट स्वतः मुक्त करता है। दोहरे शुल्क, पहुँच न मिलने, क्रेडिट न आने या लगातार समस्या पर सहायता से संपर्क करें; हम भुगतान और उपयोग रिकॉर्ड जाँचकर रिफ़ंड, क्रेडिट वापसी या उचित उपाय देंगे।",
  "Legitimate interests: security, abuse prevention, reliability, legal claims, and strictly necessary operational measurement, balanced against user rights.": "वैध हित: उपयोगकर्ता अधिकारों के साथ संतुलित सुरक्षा, दुरुपयोग रोकथाम, विश्वसनीयता, कानूनी दावे और केवल ज़रूरी संचालन माप।",
