  "Open Graphics → Motion kits for a brand reveal, speaker introduction, chapter, quote, statistic or closing card. Edit the text, accent and duration; the brand reveal can use a logo from Library. Add at the playhead, then refine the grouped layers on the timeline. Undo removes the whole insertion. These native templates use no AI credits.": "ब्रांड अनावरण, वक्ता परिचय, अध्याय, उद्धरण, आँकड़ा या समापन कार्ड के लिए ग्राफ़िक्स → मोशन किट खोलें। टेक्स्ट, अलंकरण और अवधि बदलें; ब्रांड अनावरण में लाइब्रेरी लोगो लगा सकते हैं। प्लेहेड पर जोड़कर टाइमलाइन में समूह लेयर सुधारें। पूर्ववत करने पर पूरा जोड़ हटता है। मूल टेम्पलेट में AI क्रेडिट नहीं लगते।",
  "Open Library": "लाइब्रेरी खोलें",
