  "Open Studio": "Studio खोलें",
  "Open a preset to read its direction and editable prompt. A preset supplies structure; your subject and source files make the result specific.": "निर्देशन और संपादन योग्य प्रॉम्प्ट पढ़ने के लिए प्रीसेट खोलें। प्रीसेट ढाँचा देता है; विषय और स्रोत फ़ाइल परिणाम को विशिष्ट बनाते हैं।",
  "Open a publication in Publisher to change its draft or schedule. A calendar event plans work; it does not publish a post. Check the displayed workspace timezone.": "ड्राफ़्ट या समय बदलने के लिए प्रकाशक में प्रकाशन खोलें। कैलेंडर कार्यक्रम काम की योजना है, पोस्ट नहीं भेजता। कार्यक्षेत्र का दिखाया समय क्षेत्र जाँचें।",
  "Open a result and review its source link, date, and available evidence. A hypothesis is a proposed test, not proof that a format will perform.": "परिणाम खोलकर स्रोत लिंक, तारीख़ और प्रमाण देखें। परिकल्पना प्रस्तावित परीक्षण है, फ़ॉर्मैट की सफलता का प्रमाण नहीं।",
