  "Open or create a project. Upload into Library, then drag a file to the exact time where it should begin. Preview, rename, sort, or organize files in folders before placing them.": "प्रोजेक्ट खोलें या बनाएँ। लाइब्रेरी में अपलोड करके फ़ाइल को शुरू होने के सटीक समय पर खींचें। रखने से पहले पूर्वावलोकन, नाम बदलाव, छँटाई या फ़ोल्डर व्यवस्था करें।",
