  "Open the editor and drag the file from its Library panel to a specific time. Use a finished export when preparing a publication.": "संपादक खोलकर लाइब्रेरी पैनल की फ़ाइल तय समय पर खींचें। प्रकाशन के लिए तैयार निर्यात उपयोग करें।",
  "Open the evidence behind the next steps. Activity counts describe work done in the studio; they do not replace social performance metrics.": "अगले कदमों के प्रमाण देखें। गतिविधि संख्या स्टूडियो का काम बताती है; सोशल प्रदर्शन मेट्रिक की जगह नहीं लेती।",
