  "REELassati Support": "REELassati सहायता",
  "REELassati accessibility": "REELassati सुलभता",
  "REELassati combines manual production tools with reviewable AI assistance. This page identifies where AI is used, the information sent when you invoke it, and the controls that remain with you.": "REELassati मैन्युअल निर्माण टूल और समीक्षा योग्य AI सहायता जोड़ता है। यह पेज AI के उपयोग, उसे चलाने पर भेजी जानकारी और आपके पास रहने वाले नियंत्रण बताता है।",
  "REELassati credits": "REELassati क्रेडिट",
  "REELassati designs interfaces around WCAG 2.2 AA principles: semantic structure, accessible names, visible focus, contrast, keyboard navigation, reduced motion, and feedback that does not rely on colour alone. This is an operating target, not a claim of complete certified conformance.": "REELassati WCAG 2.2 AA सिद्धांतों पर इंटरफ़ेस बनाता है: अर्थपूर्ण संरचना, सुलभ नाम, दिखता फ़ोकस, कंट्रास्ट, कीबोर्ड नेविगेशन, कम गति और रंग पर निर्भर न रहने वाला फ़ीडबैक। यह संचालन लक्ष्य है, पूर्ण प्रमाणित अनुपालन का दावा नहीं।",
  "REELassati home": "REELassati होम",
  "REELassati is intended for human-directed creative and marketing production. It is not designed to make consequential decisions about people, infer sensitive traits, or present deceptive synthetic media as authentic.": "REELassati मानव निर्देशित रचनात्मक और मार्केटिंग निर्माण के लिए है। लोगों के बारे में गंभीर निर्णय, संवेदनशील गुण का अनुमान या भ्रामक कृत्रिम मीडिया को असली बताने के लिए नहीं बना।",
  "REELassati is intended for users aged 18 or older. Material changes to this notice will be communicated appropriately before they take effect.": "REELassati 18 वर्ष या अधिक उम्र के उपयोगकर्ताओं के लिए है। इस सूचना के महत्वपूर्ण बदलाव लागू होने से पहले बताए जाएँगे।",
  "REELassati provides tools to plan, create, edit, analyse, organise, and publish short-form content. You must be at least 18 and able to enter a contract. Anyone using the service for an organisation confirms authority to bind it.": "REELassati शॉर्ट-फ़ॉर्म की योजना, निर्माण, संपादन, विश्लेषण, व्यवस्था और प्रकाशन के टूल देता है। उम्र कम से कम 18 और अनुबंध करने की क्षमता चाहिए। संगठन के लिए उपयोग करने वाला उसे बाध्य करने का अधिकार पुष्टि करता है।",
  "REELassati updates this feed internally; no action or credits are required from you.": "REELassati यह फ़ीड भीतर अपडेट करता है; आपको कोई काम या क्रेडिट नहीं चाहिए।",
