  "Returned scripts, plans, transcripts, media, and publication packages remain visible and reviewable.": "लौटाई गई स्क्रिप्ट, योजनाएँ, प्रतिलेख, मीडिया और प्रकाशन पैकेज दिखाई देते हैं और उनकी समीक्षा की जा सकती है।",
