  "Search transcript words, recorded scene observations, and clip names. Visual descriptions are searchable after source analysis exists. Search uses no AI credits. Meaning search compares English descriptions on your device against this existing text evidence.": "प्रतिलेख के शब्द, रिकॉर्ड किए गए दृश्य अवलोकन और क्लिप के नाम खोजें। स्रोत विश्लेषण होने के बाद दृश्य विवरण खोजे जा सकते हैं। खोज में AI क्रेडिट नहीं लगते। अर्थ आधारित खोज आपके डिवाइस पर अंग्रेज़ी विवरणों का मिलान इस मौजूदा टेक्स्ट प्रमाण से करती है।",
