  "Select a video or image and move the playhead inside it to capture the current pose and grade.": "वीडियो या छवि चुनें और उसकी वर्तमान पोज़ और कलर ग्रेड लेने के लिए प्लेहेड उसके भीतर ले जाएँ।",
  "Select a video or image on the timeline to apply a look.": "लुक लागू करने के लिए टाइमलाइन पर वीडियो या छवि चुनें।",
