  "Sign in or create an account to work with your own files. Pricing explains the plans; Contact opens support.": "अपनी फ़ाइलों पर काम करने के लिए साइन इन करें या खाता बनाएँ। मूल्य पेज प्लान समझाता है; संपर्क से सहायता खुलती है।",
