  "Sign up": "साइन अप करें",
  "Sign-in sessions, security, abuse prevention, theme, language, selected workspace, interface state, and the privacy preference are needed to provide requested features. They may use cookies, localStorage, or sessionStorage and are not used for advertising.": "माँगी गई सुविधाएँ देने के लिए साइन-इन सत्र, सुरक्षा, दुरुपयोग रोकथाम, थीम, भाषा, चुना हुआ कार्यक्षेत्र, इंटरफ़ेस की स्थिति और निजता प्राथमिकता ज़रूरी हैं। इनमें कुकी, localStorage या sessionStorage इस्तेमाल हो सकते हैं और ये विज्ञापन के लिए उपयोग नहीं होते।",
  "Sign-in, security, balance, preferences, and requested features.": "साइन-इन, सुरक्षा, शेष, प्राथमिकताएँ और माँगी गई सुविधाएँ।",
