  "Size is a percentage of video width. Safe margin keeps captions away from social-player controls. Preview and export use these same settings. Burned-in source captions cannot be restyled here.": "आकार वीडियो की चौड़ाई के प्रतिशत में है। सुरक्षित मार्जिन कैप्शन को सोशल प्लेयर के नियंत्रणों से दूर रखता है। पूर्वावलोकन और निर्यात यही सेटिंग इस्तेमाल करते हैं। स्रोत में स्थायी रूप से जुड़े कैप्शन की शैली यहाँ नहीं बदल सकती।",
