  "Start with my idea": "मेरे विचार से शुरू करें",
  "Start with the allowed uses and stated boundaries for the content you intend to create.": "जिस सामग्री को बनाना चाहते हैं, उसके अनुमत उपयोग और बताई गई सीमाओं से शुरू करें।",
  "Start with your files": "अपनी फ़ाइलों से शुरू करें",
