  "Styles apply to the editable captions below. Captions already inside a source video remain part of that video.": "शैलियाँ नीचे के संपादन योग्य कैप्शन पर लागू होती हैं। स्रोत वीडियो में पहले से मौजूद कैप्शन उस वीडियो का हिस्सा बने रहते हैं।",
