  "Talk to the support assistant for an immediate solution. When a person is needed, turn the conversation into a complete support ticket in one step.": "तुरंत समाधान के लिए सहायता सहायक से बात करें। व्यक्ति की ज़रूरत हो तो एक चरण में बातचीत को पूरे सहायता टिकट में बदलें।",
