  "Track names and mix settings are saved with the project. Solo sound isolates source audio; solo picture isolates visual layers. Reordering changes layer order within the same track family.": "ट्रैक के नाम और मिक्स सेटिंग प्रोजेक्ट के साथ सहेजे जाते हैं। केवल ध्वनि मोड स्रोत ऑडियो अलग करता है; केवल चित्र मोड दृश्य लेयर अलग करता है। क्रम बदलने से उसी ट्रैक समूह की लेयर का क्रम बदलता है।",
