  "Upload an audio file or choose a saved source. Transcribe it, then review names and wording before using the text.": "ऑडियो फ़ाइल अपलोड करें या सहेजा गया स्रोत चुनें। प्रतिलेखन करें, फिर टेक्स्ट इस्तेमाल करने से पहले नाम और शब्द जाँचें।",
