  "Upload reference": "संदर्भ अपलोड करें",
  "Upload storage is not configured.": "अपलोड स्टोरेज कॉन्फ़िगर नहीं है।",
  "Upload to workspace": "कार्यक्षेत्र में अपलोड करें",
  "Upload up to {{count}} files at a time.": "एक बार में अधिकतम {{count}} फ़ाइलें अपलोड करें।",
  "Upload, trim, split, caption, review AI changes, and version your short.": "अपलोड, ट्रिम, विभाजन, कैप्शन, AI बदलावों की समीक्षा और अपने शॉर्ट के संस्करण बनाएँ।",
