  "Walkthroughs show example workflows. Presets provide a starting direction that you can adapt to your own subject.": "निर्देशित उदाहरण कार्यप्रवाह दिखाते हैं। प्रीसेट शुरुआती दिशा देते हैं जिसे अपने विषय के अनुसार ढाल सकते हैं।",
