  "Waveform unavailable": "वेवफ़ॉर्म उपलब्ध नहीं है",
  "We may change or suspend features for security, law, maintenance, or provider changes. We do not promise marketing results, virality, or uninterrupted availability. Nothing excludes liability that law does not allow us to exclude or mandatory consumer remedies. Otherwise, total liability relating to the service is limited to the amount paid in the 12 months before the event.": "सुरक्षा, कानून, रखरखाव या प्रदाता के बदलावों के कारण हम सुविधाएँ बदल या रोक सकते हैं। हम मार्केटिंग परिणाम, वायरल होने या निर्बाध उपलब्धता का वादा नहीं करते। कानून जिन देयताओं को हटाने की अनुमति नहीं देता या अनिवार्य उपभोक्ता उपायों को इससे हटाया नहीं जाता। अन्यथा सेवा से संबंधित कुल देयता घटना से पहले के 12 महीनों में चुकाई गई राशि तक सीमित है।",
  "We may suspend an account for violations, security risk, non-payment, or legal duties, using proportionate measures. Italian law applies without depriving consumers of mandatory protections in their country of residence or mandatory courts. For support or complaints: ": "उल्लंघन, सुरक्षा जोखिम, गैर-भुगतान या कानूनी दायित्वों के लिए हम आनुपातिक उपायों से खाता निलंबित कर सकते हैं। उपभोक्ता के निवास देश की अनिवार्य सुरक्षा या अनिवार्य न्यायालयों से वंचित किए बिना इतालवी कानून लागू होता है। सहायता या शिकायत के लिए: ",
  "We sent a secure confirmation link to": "हमने सुरक्षित पुष्टि लिंक यहाँ भेजा है",
