  "Weekly picks use reachable direct TikTok and Reels source pages. Public dates and performance appear only when indexed evidence exposes them; unavailable values are never invented.": "साप्ताहिक चयन सीधे पहुँच योग्य TikTok और Reels स्रोत पेज इस्तेमाल करते हैं। सार्वजनिक तारीख और प्रदर्शन तभी दिखते हैं जब अनुक्रमित प्रमाण उन्हें देता है; अनुपलब्ध मान कभी गढ़े नहीं जाते।",
