  "When evidence is missing, pause publication and resolve the rights, review, provenance, or transparency question first.": "प्रमाण न हो तो प्रकाशन रोकें और पहले अधिकार, समीक्षा, उत्पत्ति या पारदर्शिता का सवाल सुलझाएँ।",
  "When reporting an issue, include the failing action and its error alongside the relevant status. Review the AI information available here when learning how the tools behave.": "समस्या बताते समय संबंधित स्थिति के साथ विफल कार्रवाई और उसकी त्रुटि दें। टूल के व्यवहार को समझते समय यहाँ उपलब्ध AI जानकारी देखें।",
  "Where applicable, you may request access, correction, deletion, restriction, portability, or objection; withdraw consent without affecting prior processing; and complain to the Italian Data Protection Authority or another competent authority. Account settings include data export and a deletion-request path.": "जहाँ लागू हो, आप पहुँच, सुधार, हटाने, प्रतिबंध, पोर्टेबिलिटी या आपत्ति का अनुरोध कर सकते हैं; पिछले प्रसंस्करण को प्रभावित किए बिना सहमति वापस ले सकते हैं; और इतालवी डेटा सुरक्षा प्राधिकरण या अन्य सक्षम प्राधिकरण से शिकायत कर सकते हैं। खाते की सेटिंग में डेटा निर्यात और हटाने के अनुरोध का रास्ता है।",
